function Invoke-ProUpgradeAudit($Session,[string]$CaseId){
 return Invoke-Command -Session $Session -ArgumentList $CaseId -ScriptBlock {
  param($caseId)
  $ErrorActionPreference='Stop';$config=[IO.File]::ReadAllText(('C:\MuLab\approved\upgrade-'+$caseId+'-config.json'))|ConvertFrom-Json
  if($caseId -notmatch '^[a-f0-9]{32}$' -or $config.caseId -ne $caseId -or $config.directory -ne ('C:\MuLab\public\upgrade-'+$caseId) -or (Get-LocalUser $config.userName).SID.Value -ne $config.userSid){throw 'Bound upgrade audit required'}
  $finished=[IO.File]::ReadAllText(('C:\MuLab\approved\upgrade-'+$caseId+'-cleanup-result.json'))|ConvertFrom-Json;if(-not $finished.complete -or -not $finished.processExitConfirmed -or -not $finished.brokerExitConfirmed -or -not $finished.nested.removed){throw 'Completed exact cleanup receipt required'}
  $actors=@(Get-CimInstance Win32_Process|Where-Object{$_.ExecutablePath -and ($_.ExecutablePath.StartsWith($config.directory,[StringComparison]::OrdinalIgnoreCase) -or $_.ExecutablePath -eq $config.launcher -or $_.ExecutablePath -like '*MuCodeSandbox-HyperVBroker-v1\bin\hv-*.exe' -or $_.CommandLine -like ('*'+$caseId+'*'))});if($actors.Count -or @(Get-VM).Count -or @(Get-VMSwitch|Where-Object Name -match '^mu-win-[a-f0-9]{32}$').Count){throw 'Upgrade actors or nested allocations remain'}
  $grant=if($config.fixtureParentAcl){$config.fixtureParentAcl}else{$config.cleanupRetry};if(-not $grant -or $grant.directory -ne 'C:\MuLab\public' -or $grant.rights -ne 129 -or $grant.inherits){throw 'Bound fixture-only parent permission receipt required'}
  $acl=Get-Acl -LiteralPath $grant.directory;if($acl.Sddl -ceq $grant.newSddl){$rules=@($acl.Access|Where-Object{$_.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value -eq $config.userSid});if($rules.Count -ne 1 -or $rules[0].IsInherited -or $rules[0].InheritanceFlags -ne [Security.AccessControl.InheritanceFlags]::None){throw 'Fixture permission no longer matches the exact temporary rule'};$acl.RemoveAccessRuleSpecific($rules[0]);Set-Acl -LiteralPath $grant.directory -AclObject $acl};if((Get-Acl -LiteralPath $grant.directory).Sddl -cne $grant.oldSddl){throw 'Original fixture parent ACL restoration unconfirmed'}
  $retainedFailure=$null;if($config.cleanupRetry){$failedFile=Join-Path $config.cleanupRetry.history 'approved-failed-result.json';if((Get-FileHash $failedFile).Hash.ToLowerInvariant() -ne $config.cleanupRetry.failedResultSha256){throw 'Historical failed cleanup receipt changed'};$failed=[IO.File]::ReadAllText($failedFile)|ConvertFrom-Json;if($failed.complete -ne $false -or $failed.caseId -ne $caseId -or -not $failed.processExitConfirmed -or -not $failed.brokerExitConfirmed){throw 'Exact historical terminal failure missing'};$retainedFailure=@{complete=$false;checksPassed=@($failed.checks).Count;sha256=$config.cleanupRetry.failedResultSha256;fixtureOnlyRepair=$true;encryptedBytesUnchanged=$config.cleanupRetry.encryptedBytesUnchanged;originalDiskUnchanged=$config.cleanupRetry.originalDiskUnchanged}}
  $users=Join-Path $env:ProgramData 'MuCodeSandbox-HyperVBroker-v1/users';$owners=@();foreach($root in @(Get-ChildItem -LiteralPath $users -Directory)){
   $primary=Join-Path $root.FullName 'vms.json';$backup=Join-Path $root.FullName 'vms.backup.json';$disks=Join-Path $root.FullName 'vms';if((Test-Path -LiteralPath $disks) -and @(Get-ChildItem -LiteralPath $disks -Force).Count){throw 'Protected owner storage remains'};if(-not(Test-Path -LiteralPath $primary)){if(Test-Path -LiteralPath $backup){throw 'A protected backup has no matching primary'};continue};$ledger=[IO.File]::ReadAllText($primary)|ConvertFrom-Json
   if($ledger.version -ne 2 -or $ledger.ownerSid -ne $root.Name -or @($ledger.records.psobject.Properties).Count -or (Get-FileHash $primary).Hash -ne (Get-FileHash $backup).Hash -or @(Get-ChildItem -LiteralPath (Join-Path $root.FullName 'vms') -Force).Count){throw 'A protected owner allocation remains or its ledger differs'};$owners+=$root.Name
  };if($config.userSid -notin $owners){throw 'The upgrade user protected ledger was not audited'}
  $app=Join-Path $config.directory 'retained-app';$hashes=@{};foreach($file in @('package.json','desktop/windows/main.cjs','dist-server/windows-release.json','dist-server/server/platform/windows/broker.js','dist-server/server/platform/windows/runtime.js','dist-server/server/platform/windows/manager.js','dist-server/server/platform/windows/service.js','dist-server/server/platform/windows/config.js','dist-server/server/platform/windows/disk-growth.js','dist-server/server/platform/windows/translation-settings.js')){$hashes[$file]=(Get-FileHash -LiteralPath (Join-Path $app $file)).Hash.ToLowerInvariant()}
  $bin=Join-Path $env:ProgramData 'MuCodeSandbox-HyperVBroker-v1/bin';if((Get-FileHash (Join-Path $bin 'current.json')).Hash.ToLowerInvariant() -ne $config.defaultBrokerPointerSha256 -or (Get-Service vmms).Status -ne 'Running'){throw 'The original default broker or VMMS changed'}
  return @{complete=$true;caseId=$caseId;userSid=$config.userSid;protectedOwners=$owners;actors=0;nestedGuests=0;privateSwitches=0;registeredGuests=0;runtimeDirectories=0;registrationCopiesEqual=$true;defaultBrokerPointerUnchanged=$true;vmmsRunning=$true;fixtureParentAclRestored=$true;retainedFailure=$retainedFailure;artifactHashes=$hashes;clientSha256=(Get-FileHash (Join-Path $config.tools 'pro-upgrade-client.mjs')).Hash.ToLowerInvariant();stationSourceSha256=(Get-FileHash (Join-Path $config.tools 'ProUpgradeStation.cs')).Hash.ToLowerInvariant();brokers=$config.brokers;aiWebsitesVisited=0}
 }
}
